(4423039, 636940, 43774, '<td valign="top">Wonderful job of framing this, love the blue sky. That is an amazing building.</td>', 'Wonderful job of framing this, love the blue sky. That is an amazing building.', '2008-01-24 21:28:19.000000', NULL, 1),
(4423041, 634952, 43774, '<td valign="top">So cute! Great colours too.</td>', 'So cute! Great colours too.', '2008-01-24 21:28:31.000000', NULL, 1),
(4423044, 635937, 43774, '<td valign="top">A bit odd but well photographed with good lighting.</td>', 'A bit odd but well photographed with good lighting.', '2008-01-24 21:28:54.000000', NULL, 1),
(4423046, 635639, 43774, '<td valign="top">Wonderful perspective, I feel like I am about to be grabbed.</td>', 'Wonderful perspective, I feel like I am about to be grabbed.', '2008-01-24 21:29:25.000000', NULL, 1),
(4423047, 635489, 43774, '<td valign="top">The soft light in this is gorgeous.</td>', 'The soft light in this is gorgeous.', '2008-01-24 21:29:43.000000', NULL, 1),
(4423084, 636336, 60505, '<td valign="top">my eyes kept scanning left to right and back, across the center of the photo, composition could be improved by trying to get my eyes move in a circle around the pic, or at minimum in a triangle. too much empty space on top and table horizon may be better place on the thirds, either i3 way from the bottom or from the to. Empty glass is a distraction. I would taken a vertical format pic and placed the bottles and other elements close together. I like the Brie!</td>', 'my eyes kept scanning left to right and back, across the center of the photo, composition could be improved by trying to get my eyes move in a circle around the pic, or at minimum in a triangle. too much empty space on top and table horizon may be better place on the thirds, either i3 way from the bottom or from the to. Empty glass is a distraction. I would taken a vertical format pic and placed the bottles and other elements close together. I like the Brie!', '2008-01-24 21:47:50.000000', NULL, 1),
(4423098, 636511, 60505, '<td valign="top">very arresting image. Great composition.</td>', 'very arresting image. Great composition.', '2008-01-24 21:51:57.000000', NULL, 1),
(4423193, 636881, 71651, '<td valign="top">Such an interesting shot and idea but the picture is out of focus.</td>', 'Such an interesting shot and idea but the picture is out of focus.', '2008-01-24 22:33:07.000000', NULL, 1),
(4423196, 636835, 89192, '<td valign="top">I love it.  I know its against the rules here but, if you remove the twigs over the horizon and some of the dirt specks in the snow it would help. I give it a 7.</td>', 'I love it.  I know its against the rules here but, if you remove the twigs over the horizon and some of the dirt specks in the snow it would help. I give it a 7.', '2008-01-24 22:33:38.000000', NULL, 1),
(4423206, 636881, 89192, '<td valign="top">The eye should be in focus.  Great idea though.</td>', 'The eye should be in focus.  Great idea though.', '2008-01-24 22:38:06.000000', NULL, 1),
(4423212, 635326, 89192, '<td valign="top">What are all those dots?  Bugs?</td>', 'What are all those dots?  Bugs?', '2008-01-24 22:43:55.000000', NULL, 1),
