(4423611, 636728, 5364, '<td valign="top">I would have preferred to see all of the window rather than cropping it off, but a good choice to present it in monochrome.</td>', 'I would have preferred to see all of the window rather than cropping it off, but a good choice to present it in monochrome.', '2008-01-25 03:08:40.000000', NULL, 1),
(4423614, 635642, 5364, '<td valign="top">Nice idea. I think a slighter darker sky would have helped, but I do realise that would have put the moon in the wrong place as well.</td>', 'Nice idea. I think a slighter darker sky would have helped, but I do realise that would have put the moon in the wrong place as well.', '2008-01-25 03:12:52.000000', NULL, 1),
(4423661, 636820, 86799, '<td valign="top">very nice.  Way above all the routine pet pics.  Actually striking.  Good work!</td>', 'very nice.  Way above all the routine pet pics.  Actually striking.  Good work!', '2008-01-25 06:08:56.000000', NULL, 1),
(4423662, 637026, 86799, '<td valign="top">Cool.  Well executed.</td>', 'Cool.  Well executed.', '2008-01-25 06:11:26.000000', NULL, 1),
(4423664, 634780, 86799, '<td valign="top">Needs more light on the subject.  The frame dominates a little too much, IMO.  Nice, but I had to look twice to see the sax man.</td>', 'Needs more light on the subject.  The frame dominates a little too much, IMO.  Nice, but I had to look twice to see the sax man.', '2008-01-25 06:16:53.000000', NULL, 1),
(4423668, 634457, 86799, '<td valign="top">I really like this.  The flavor is very smooth.  I wish the boat was just a little bigger.  Nice image, though.</td>', 'I really like this.  The flavor is very smooth.  I wish the boat was just a little bigger.  Nice image, though.', '2008-01-25 06:24:12.000000', NULL, 1),
(4423672, 635489, 86799, '<td valign="top">Excellent work.  Very good framing, that doesn''t overpower the subject.  I hope this does well.</td>', 'Excellent work.  Very good framing, that doesn''t overpower the subject.  I hope this does well.', '2008-01-25 06:27:52.000000', NULL, 1);
