(4425850, 635225, 48697, '<td valign="top">cool idea but I feel the frame and the hand could be sharper or more in focus.</td>', 'cool idea but I feel the frame and the hand could be sharper or more in focus.', '2008-01-26 01:44:29.000000', NULL, 1),
(4425853, 637118, 48697, '<td valign="top">I ran all out of those in my fridge, reminds me to restock. Cool idea and nicely executed.</td>', 'I ran all out of those in my fridge, reminds me to restock. Cool idea and nicely executed.', '2008-01-26 01:45:36.000000', NULL, 1),
(4425860, 635634, 48697, '<td valign="top">I like the scene though I feel the tree is a distraction.  Maybe including more of the tree or completely cropping the tree out could help the composition.</td>', 'I like the scene though I feel the tree is a distraction.  Maybe including more of the tree or completely cropping the tree out could help the composition.', '2008-01-26 01:48:11.000000', NULL, 1),
(4425864, 636997, 48697, '<td valign="top">Seems a bit bright and blown out to me.  I think since the shot is overexposed the contrast and details suffer. I do like the tone in this shot.</td>', 'Seems a bit bright and blown out to me.  I think since the shot is overexposed the contrast and details suffer. I do like the tone in this shot.', '2008-01-26 01:49:47.000000', NULL, 1),
(4425867, 637017, 48697, '<td valign="top">Beautiful scene, would love to be there right now.  Nice framing and vibrant blue and greens.  I do feel it is a bit noisey and could benifit with a run through a noise reduction program.</td>', 'Beautiful scene, would love to be there right now.  Nice framing and vibrant blue and greens.  I do feel it is a bit noisey and could benifit with a run through a noise reduction program.', '2008-01-26 01:51:34.000000', NULL, 1),
(4425914, 636974, 5364, '<td valign="top">This has potential, but you needed to rotate it to get the horizon level and you needed to get the camera to focus of the landscape rather than the foreground.</td>', 'This has potential, but you needed to rotate it to get the horizon level and you needed to get the camera to focus of the landscape rather than the foreground.', '2008-01-26 04:19:06.000000', NULL, 1),
(4426051, 634884, 41864, '<td valign="top">Looks really cute, but IMO the photo is much too small. Very nice idea.</td>', 'Looks really cute, but IMO the photo is much too small. Very nice idea.', '2008-01-26 09:13:55.000000', NULL, 1),
(4426056, 635168, 41864, '<td valign="top">Light on her face seems a bit harsh, especially on her cheek and forehead. Composition is good, maybe a little tightly cropped on the top.</td>', 'Light on her face seems a bit harsh, especially on her cheek and forehead. Composition is good, maybe a little tightly cropped on the top.', '2008-01-26 09:16:29.000000', NULL, 1),
(4426057, 636729, 41864, '<td valign="top">Focus is a little off. Good capture.</td>', 'Focus is a little off. Good capture.', '2008-01-26 09:17:06.000000', NULL, 1),
(4426060, 636000, 41864, '<td valign="top">Nice shot. Maybe a litle more saturation to bring out the blues.</td>', 'Nice shot. Maybe a litle more saturation to bring out the blues.', '2008-01-26 09:19:41.000000', NULL, 1),
(4426061, 636634, 41864, '<td valign="top">Hard luck I''ve trips of 2''s!!! <br/>Nice shot. Little bit yellow...slight whitle balance adjustment would improve this greatly..</td>', 'Hard luck I''ve trips of 2''s!!! Nice shot. Little bit yellow...slight whitle balance adjustment would improve this greatly..', '2008-01-26 09:22:15.000000', NULL, 1),
(4426065, 636754, 41864, '<td valign="top">Great shot. Perhaps cropping the the gap on the left would be better?? What a beautiful place.</td>', 'Great shot. Perhaps cropping the the gap on the left would be better?? What a beautiful place.', '2008-01-26 09:24:06.000000', NULL, 1),
(4426121, 636075, 84779, '<td valign="top">very nice shot</td>', 'very nice shot', '2008-01-26 10:15:24.000000', NULL, 1),
