(4426188, 636770, 85849, '<td valign="top">Looks guilty to me!<br/> <br/>Nice shot.</td>', 'Looks guilty to me! Nice shot.', '2008-01-26 10:44:01.000000', NULL, 1),
(4426191, 637094, 89005, '<td valign="top">I think it is a little bit too dark.</td>', 'I think it is a little bit too dark.', '2008-01-26 10:44:27.000000', NULL, 1),
(4426206, 634780, 89005, '<td valign="top">I think the exposure is a bit off with regards to what is the subject. Maybe more exposure time to let the saxophone man be lighter. The light outside will be more overexposed but as it already is overexposed it wouldent hurt.<br/> <br/>But then again, then "framing" would disapper.  Hmm maybe you took the best decision.</td>', 'I think the exposure is a bit off with regards to what is the subject. Maybe more exposure time to let the saxophone man be lighter. The light outside will be more overexposed but as it already is overexposed it wouldent hurt. But then again, then "framing" would disapper.  Hmm maybe you took the best decision.', '2008-01-26 10:48:53.000000', NULL, 1),
(4426207, 636099, 85849, '<td valign="top">Nice depth of feild</td>', 'Nice depth of feild', '2008-01-26 10:49:20.000000', NULL, 1),
(4426210, 635448, 89005, '<td valign="top">A bit too dark maybe. Nice motive though.</td>', 'A bit too dark maybe. Nice motive though.', '2008-01-26 10:50:39.000000', NULL, 1),
