(4433537, 636999, 66193, '<td valign="top">gorgeous shot.  I love the B&amp;W conversion, and the windblown dress.  great capture. 9.</td>', 'gorgeous shot.  I love the B&W conversion, and the windblown dress.  great capture. 9.', '2008-01-28 15:02:57.000000', NULL, 1),
(4433541, 636730, 66193, '<td valign="top">fantastic image.  I love the harsh processing, it fits well with the image. 9.</td>', 'fantastic image.  I love the harsh processing, it fits well with the image. 9.', '2008-01-28 15:03:29.000000', NULL, 1),
(4433543, 635979, 66193, '<td valign="top">I like the color combinations here.  looks like a palette from a designer''s handbook. 8.</td>', 'I like the color combinations here.  looks like a palette from a designer''s handbook. 8.', '2008-01-28 15:04:02.000000', NULL, 1),
(4433548, 634984, 66193, '<td valign="top">nice capture here. the white spots are a little distracting in the shadows, but that''s the limitation of basic editing. 8.</td>', 'nice capture here. the white spots are a little distracting in the shadows, but that''s the limitation of basic editing. 8.', '2008-01-28 15:05:02.000000', NULL, 1),
