(4435400, 635515, 89192, '<td valign="top">Oh, man!  That''s awesome.  Maybe some scribbles on the bottom like people do on polaroids?  I don''t know.  I love it though.  Very creative.</td>', 'Oh, man!  That''s awesome.  Maybe some scribbles on the bottom like people do on polaroids?  I don''t know.  I love it though.  Very creative.', '2008-01-29 00:27:09.000000', NULL, 1),
(4435405, 636605, 89192, '<td valign="top">I like it but, I''m not sure its really framed by anything.</td>', 'I like it but, I''m not sure its really framed by anything.', '2008-01-29 00:28:18.000000', NULL, 1),
(4435412, 635021, 63812, '<td valign="top">???</td>', '???', '2008-01-29 00:30:28.000000', NULL, 1),
(4435418, 637026, 89192, '<td valign="top">What did you use to light up the ball?</td>', 'What did you use to light up the ball?', '2008-01-29 00:32:34.000000', NULL, 1),
(4435428, 635909, 89192, '<td valign="top">I love the composition but it seems over processed.  If that''s what you were going for then good job.  I don''t mean for that to sound negetive.</td>', 'I love the composition but it seems over processed.  If that''s what you were going for then good job.  I don''t mean for that to sound negetive.', '2008-01-29 00:35:45.000000', NULL, 1),
(4435432, 636544, 89192, '<td valign="top">I cant decide if the large roof area is destracting or adds to the photo.</td>', 'I cant decide if the large roof area is destracting or adds to the photo.', '2008-01-29 00:37:16.000000', NULL, 1),
