INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4435451, 636573, 89192, '<td valign="top">I think a tighter shot or crop if possible would have helped.</td>', 'I think a tighter shot or crop if possible would have helped.', '2008-01-29 00:45:08.000000', NULL, 1),
(4435455, 633997, 89192, '<td valign="top">Focus seems to be on the palm leaf rather than the background.  Nice composition though.</td>', 'Focus seems to be on the palm leaf rather than the background.  Nice composition though.', '2008-01-29 00:47:22.000000', NULL, 1),
(4435461, 635321, 89192, '<td valign="top">The dark areas are distracting.  Crop the sides a bit and it will help.</td>', 'The dark areas are distracting.  Crop the sides a bit and it will help.', '2008-01-29 00:50:05.000000', NULL, 1),
(4435464, 635979, 89192, '<td valign="top">Fits the challenge but it seems really flat and colorless.  I like your framing a frame idea though.</td>', 'Fits the challenge but it seems really flat and colorless.  I like your framing a frame idea though.', '2008-01-29 00:52:38.000000', NULL, 1),
(4435766, 636531, 80326, '<td valign="top">You have dust spots, nice framing though.</td>', 'You have dust spots, nice framing though.', '2008-01-29 07:25:26.000000', NULL, 1),
(4435804, 636544, 39850, '<td valign="top">7 - Like this.  Any variation in the crop of the roof would still look good (although wonder whether it may have made the image stronger with less roof, but your call of course), my only real ''complaint'' is that it needs a nudge up on the right... unless it is intentionally tilted a little.</td>', '7 - Like this.  Any variation in the crop of the roof would still look good (although wonder whether it may have made the image stronger with less roof, but your call of course), my only real ''complaint'' is that it needs a nudge up on the right... unless it is intentionally tilted a little.', '2008-01-29 07:59:40.000000', NULL, 1),
(4435847, 634457, 67258, '<td valign="top">Impressive exposure and depth of field!</td>', 'Impressive exposure and depth of field!', '2008-01-29 08:10:07.000000', NULL, 1),
(4435867, 636421, 67258, '<td valign="top">Superb composition, but the photo does look a little flat - I suspect you have had the same dark, dull, grey days as we have had in Yokshire.</td>', 'Superb composition, but the photo does look a little flat - I suspect you have had the same dark, dull, grey days as we have had in Yokshire.', '2008-01-29 08:20:06.000000', NULL, 1),
(4435901, 636099, 30049, '<td valign="top">Cool freeze action shot.  Not sure that it''s really framed as suggested in the challenge description, but it''s an interesting study in motion.</td>', 'Cool freeze action shot.  Not sure that it''s really framed as suggested in the challenge description, but it''s an interesting study in motion.', '2008-01-29 08:39:46.000000', NULL, 1),
(4435911, 637041, 30049, '<td valign="top">Everybody has what?  Not getting it, sorry.  As for the photo it''s certainly framed correctly.  The subject(s) in the background are interesting in that I wonder what they''re up to.</td>', 'Everybody has what?  Not getting it, sorry.  As for the photo it''s certainly framed correctly.  The subject(s) in the background are interesting in that I wonder what they''re up to.', '2008-01-29 08:43:44.000000', NULL, 1),
(4435915, 635637, 30049, '<td valign="top">I keep tilting my head to see this straight.  :)  I take it the framing is the small area of wood top right and right?</td>', 'I keep tilting my head to see this straight.  :)  I take it the framing is the small area of wood top right and right?', '2008-01-29 08:45:01.000000', NULL, 1),
(4435917, 637081, 30049, '<td valign="top">This is interesting in the color tones used.  Seems a bit oversharpened.</td>', 'This is interesting in the color tones used.  Seems a bit oversharpened.', '2008-01-29 08:46:18.000000', NULL, 1),
(4435937, 636821, 30049, '<td valign="top">They''re certainly checking you out, eh?  :)  I have no idea how this could have been done any differently under basic editing rules, and please don''t take offense to this.  The image overall, because of the grey skies I guess, has a flat dull feel to it.  I understand you wanted to include the incoming birds, which I probably would have as well...it''s just so greyish.  <br/> <br/>I would like to see more detail on the foreground birds.  The detail is lost because of distance and the high contrast lighting on them.  <br/> <br/>Don''t know if it was possible (appears you may have been crouched down, but this shot a little more elevated and tighter on the birds would have kept the framing, lost some of the grey sky, and brought the birds in closer for a better look.  All JMO of course.  :-)  Good luck in the challenge.</td>', 'They''re certainly checking you out, eh?  :)  I have no idea how this could have been done any differently under basic editing rules, and please don''t take offense to this.  The image overall, because of the grey skies I guess, has a flat dull feel to it.  I understand you wanted to include the incoming birds, which I probably would have as well...it''s just so greyish.   I would like to see more detail on the foreground birds.  The detail is lost because of distance and the high contrast lighting on them.   Don''t know if it was possible (appears you may have been crouched down, but this shot a little more elevated and tighter on the birds would have kept the framing, lost some of the grey sky, and brought the birds in closer for a better look.  All JMO of course.  :-)  Good luck in the challenge.', '2008-01-29 08:52:24.000000', NULL, 1),
(4435943, 636000, 30049, '<td valign="top">Postcard type framing.  Very nice.  At first glance I thought this was IR, then I realized it''s the REAL deal - not fake looking white snow.  Cool!  :-)</td>', 'Postcard type framing.  Very nice.  At first glance I thought this was IR, then I realized it''s the REAL deal - not fake looking white snow.  Cool!  :-)', '2008-01-29 08:53:38.000000', NULL, 1),
(4435952, 635715, 30049, '<td valign="top">Ok.  It''s framed...kinda.  Quite a busy image with all those intersecting lines.</td>', 'Ok.  It''s framed...kinda.  Quite a busy image with all those intersecting lines.', '2008-01-29 08:54:55.000000', NULL, 1),
(4435962, 635741, 30049, '<td valign="top">Must have been a man that last used the toilet...the seat''s up!  :-P  Clever idea for the challenge.  The slightly soft image gives a sense of being there as well, instead of being crisp/sharp.  May have wanted to cool the color temp just a tad as it has a strong yellowish tint from the lights.  Not a big deal, just an observation.  Good luck in the challenge with this.</td>', 'Must have been a man that last used the toilet...the seat''s up!  :-P  Clever idea for the challenge.  The slightly soft image gives a sense of being there as well, instead of being crisp/sharp.  May have wanted to cool the color temp just a tad as it has a strong yellowish tint from the lights.  Not a big deal, just an observation.  Good luck in the challenge with this.', '2008-01-29 08:57:47.000000', NULL, 1),
(4435980, 637093, 30049, '<td valign="top">Here''s a couple of trees that work ok for framing.  :)  Looks like a pretty scene.  I''m losing a sense of depth perception somewhat.  I think it''s because the tree on the right is not giving a clear break and is blending in?  I''m a fan of B&amp;W and this may have been the best approach, no idea without seeing it in color.  I do wonder tho if color would have given more depth to this.  Just some observations.  Still a lovely image.  Good luck in the challenge.</td>', 'Here''s a couple of trees that work ok for framing.  :)  Looks like a pretty scene.  I''m losing a sense of depth perception somewhat.  I think it''s because the tree on the right is not giving a clear break and is blending in?  I''m a fan of B&W and this may have been the best approach, no idea without seeing it in color.  I do wonder tho if color would have given more depth to this.  Just some observations.  Still a lovely image.  Good luck in the challenge.', '2008-01-29 09:01:07.000000', NULL, 1),
(4435987, 636336, 30049, '<td valign="top">This is a hard subject to pull off correctly.  I know, I''ve tried once.  :)  The lighting and reflections are challenging to control on the glass and bottles.  In this case the lighting it causing some harsh reflections.  The POV taken is causing the back edge to distract as it cuts thru the objects.  A lower angle, or different background would help this some.  As for the framing part of this challenge, I''m not sure that this is really the idea.  Personally I think the framing elements should be more in the foreground or background as suggested in the challenge description.  <br/> <br/>All JMO and observations.  :)  Good luck in the challenge.</td>', 'This is a hard subject to pull off correctly.  I know, I''ve tried once.  :)  The lighting and reflections are challenging to control on the glass and bottles.  In this case the lighting it causing some harsh reflections.  The POV taken is causing the back edge to distract as it cuts thru the objects.  A lower angle, or different background would help this some.  As for the framing part of this challenge, I''m not sure that this is really the idea.  Personally I think the framing elements should be more in the foreground or background as suggested in the challenge description.   All JMO and observations.  :)  Good luck in the challenge.', '2008-01-29 09:05:02.000000', NULL, 1),
(4435991, 636762, 30049, '<td valign="top">Hey.  Now how cool is that?!  :-)  Nice catch.  I''d have been tempted, after getting this shot, to switch to burst mode and whistle.  See what you get on the reaction.  :-P  Good luck in the challenge.</td>', 'Hey.  Now how cool is that?!  :-)  Nice catch.  I''d have been tempted, after getting this shot, to switch to burst mode and whistle.  See what you get on the reaction.  :-P  Good luck in the challenge.', '2008-01-29 09:06:54.000000', NULL, 1),
(4436297, 635451, 85255, '<td valign="top">Not quite certain what is being framed here...  perhaps it is the face, framed by the hair?</td>', 'Not quite certain what is being framed here...  perhaps it is the face, framed by the hair?', '2008-01-29 11:24:48.000000', NULL, 1),
(4436303, 636848, 85255, '<td valign="top">Very ''busy'' shot.  The eye cannot focus nor flow within the picture.</td>', 'Very ''busy'' shot.  The eye cannot focus nor flow within the picture.', '2008-01-29 11:27:32.000000', NULL, 1),
(4436308, 636714, 85255, '<td valign="top">Interesting ''multiple'' frame work with the fracmented reflective material.</td>', 'Interesting ''multiple'' frame work with the fracmented reflective material.', '2008-01-29 11:29:20.000000', NULL, 1),
(4436316, 636884, 85255, '<td valign="top">Nice, but would rather have more of the dark background than snow as the light coloured grass seems to ''melt'' into the whites.</td>', 'Nice, but would rather have more of the dark background than snow as the light coloured grass seems to ''melt'' into the whites.', '2008-01-29 11:33:10.000000', NULL, 1),
(4436338, 637070, 30049, '<td valign="top">I really like this.  Not sure why.  I think maybe it''s the competing diagonals (branches vs shadows).  You have framing in here, albeit non-traditional, that could be too subtle for many.  Hope that doesn''t hurt your score too much.  I''ve picked this for my top 3...good luck getting there!  :)  Well done.</td>', 'I really like this.  Not sure why.  I think maybe it''s the competing diagonals (branches vs shadows).  You have framing in here, albeit non-traditional, that could be too subtle for many.  Hope that doesn''t hurt your score too much.  I''ve picked this for my top 3...good luck getting there!  :)  Well done.', '2008-01-29 11:45:33.000000', NULL, 1),
(4436343, 635790, 30049, '<td valign="top">I''m very surprised we didn''t see more of this in the challenge.  It''s perfect for this and you''ve done very well in getting the shot.  Didn''t get a chance for a "do-over" on this one (unless you know the jogger, but I doubt it).  The lines, the patterns, the contrast - all add up to an interesting and intriquing photo.  Nicely done!  A top 3 choice for me.  Hope you make it there!  :-)</td>', 'I''m very surprised we didn''t see more of this in the challenge.  It''s perfect for this and you''ve done very well in getting the shot.  Didn''t get a chance for a "do-over" on this one (unless you know the jogger, but I doubt it).  The lines, the patterns, the contrast - all add up to an interesting and intriquing photo.  Nicely done!  A top 3 choice for me.  Hope you make it there!  :-)', '2008-01-29 11:47:41.000000', NULL, 1),
(4436353, 636884, 30049, '<td valign="top">Found or created, doesn''t matter.  I like it.  The contrast is pleasing and I like the way the grass is coming thru on a diagonal.  You''ve handled the exposure on this quite well with the snow being white (not grey) and didn''t let the highlights on the grass blow out.  Well done!  One of my top 3 picks for this challenge.  Hope you get there!  :-)</td>', 'Found or created, doesn''t matter.  I like it.  The contrast is pleasing and I like the way the grass is coming thru on a diagonal.  You''ve handled the exposure on this quite well with the snow being white (not grey) and didn''t let the highlights on the grass blow out.  Well done!  One of my top 3 picks for this challenge.  Hope you get there!  :-)', '2008-01-29 11:50:11.000000', NULL, 1),
(4436356, 636511, 30049, '<td valign="top">Clever.  Wonderfully seen and captured.</td>', 'Clever.  Wonderfully seen and captured.', '2008-01-29 11:51:36.000000', NULL, 1),
(4436361, 636730, 30049, '<td valign="top">This is fun.  Who says a centered composition can''t work once in awhile?  :-)  May be just a bit over processed and bordering on the edge of becoming too painterly/graphic.  It is nice tho...in my top 10.  Good luck!</td>', 'This is fun.  Who says a centered composition can''t work once in awhile?  :-)  May be just a bit over processed and bordering on the edge of becoming too painterly/graphic.  It is nice tho...in my top 10.  Good luck!', '2008-01-29 11:54:01.000000', NULL, 1),
(4436362, 636393, 30049, '<td valign="top">I like the color tone...gives it a feeling of wintertime cold with the blue.  Nice positioning of the bird in your comp.  Technicals are on the mark (DOF, focus, etc...).  Should do ok with this one.  Good luck!</td>', 'I like the color tone...gives it a feeling of wintertime cold with the blue.  Nice positioning of the bird in your comp.  Technicals are on the mark (DOF, focus, etc...).  Should do ok with this one.  Good luck!', '2008-01-29 11:54:05.000000', NULL, 1),
(4436367, 636339, 30049, '<td valign="top">Good eye to see this.  It''s like the viewer is getting a glimpse of someone else''s moment peeking thru the shades, although I doubt the performer would mind.  :-)  Well done!</td>', 'Good eye to see this.  It''s like the viewer is getting a glimpse of someone else''s moment peeking thru the shades, although I doubt the performer would mind.  :-)  Well done!', '2008-01-29 11:55:24.000000', NULL, 1),
(4436369, 634194, 30049, '<td valign="top">Minimalistic framing.  :-)  Clever.  Good eye to see this.  Not only is the framing part fun, the rest of the image is pleasing to look at with nice bright colors and subjects of interest.  Good luck in the challenge.</td>', 'Minimalistic framing.  :-)  Clever.  Good eye to see this.  Not only is the framing part fun, the rest of the image is pleasing to look at with nice bright colors and subjects of interest.  Good luck in the challenge.', '2008-01-29 11:56:37.000000', NULL, 1),
(4436371, 637094, 30049, '<td valign="top">I like how you''ve put this together.  The earth tones are right on the money for the subject, and the tilt sets up the composition in a way that is pleasing to the eye.  Creative and well done!  Good luck in the challenge.</td>', 'I like how you''ve put this together.  The earth tones are right on the money for the subject, and the tilt sets up the composition in a way that is pleasing to the eye.  Creative and well done!  Good luck in the challenge.', '2008-01-29 11:58:01.000000', NULL, 1),
(4436375, 636441, 30049, '<td valign="top">This is a shot I could see myself taking and my wife and kids going "put the camera away now".  :-)  This is fun to look at.  Well framed and the eye easily moves into the image to follow the lineup.  Nicely done!</td>', 'This is a shot I could see myself taking and my wife and kids going "put the camera away now".  :-)  This is fun to look at.  Well framed and the eye easily moves into the image to follow the lineup.  Nicely done!', '2008-01-29 11:59:22.000000', NULL, 1),
(4436955, 636954, 86799, '<td valign="top">Nice.</td>', 'Nice.', '2008-01-29 15:39:25.000000', NULL, 1),
(4437268, 635790, 43774, '<td valign="top">I love the repetitive shapes and lines here and the composition.</td>', 'I love the repetitive shapes and lines here and the composition.', '2008-01-29 17:55:10.000000', NULL, 1),
(4437270, 636955, 43774, '<td valign="top">Very good framing, nice textures and detail.</td>', 'Very good framing, nice textures and detail.', '2008-01-29 17:55:25.000000', NULL, 1),
(4437273, 636531, 43774, '<td valign="top">I like this. A nice landscape in the background and good detail in front.</td>', 'I like this. A nice landscape in the background and good detail in front.', '2008-01-29 17:55:53.000000', NULL, 1),
(4437276, 637021, 43774, '<td valign="top">Beautiful! Love the fish-eye look</td>', 'Beautiful! Love the fish-eye look', '2008-01-29 17:56:13.000000', NULL, 1),
(4437277, 636835, 43774, '<td valign="top">Very cool sculpture and good framing.</td>', 'Very cool sculpture and good framing.', '2008-01-29 17:56:46.000000', NULL, 1),
(4437278, 635674, 43774, '<td valign="top">Very cute!</td>', 'Very cute!', '2008-01-29 17:56:54.000000', NULL, 1),
(4437360, 636506, 33672, '<td valign="top">One of the Best in the theme. 9</td>', 'One of the Best in the theme. 9', '2008-01-29 18:26:05.000000', NULL, 1),
(4437553, 636558, 86368, '<td valign="top">the pony in the background is a little distracting..i think its a pony. perhaps it wouldve been better with the focus in the background. i like the idea though.</td>', 'the pony in the background is a little distracting..i think its a pony. perhaps it wouldve been better with the focus in the background. i like the idea though.', '2008-01-29 20:02:11.000000', NULL, 1),
(4437556, 637042, 86368, '<td valign="top">wow where did you shoot this? i really like this one. im not sure if all of the branches up top are necessary and the bird couldve been brighter. but way to go!</td>', 'wow where did you shoot this? i really like this one. im not sure if all of the branches up top are necessary and the bird couldve been brighter. but way to go!', '2008-01-29 20:03:35.000000', NULL, 1),
(4437559, 635515, 86368, '<td valign="top">nice shot. i like the lighting and the simplicity of the photograph.</td>', 'nice shot. i like the lighting and the simplicity of the photograph.', '2008-01-29 20:05:07.000000', NULL, 1),
(4437561, 637087, 86368, '<td valign="top">this is great.</td>', 'this is great.', '2008-01-29 20:05:49.000000', NULL, 1),
(4437577, 635504, 88352, '<td valign="top">Not sure where the framing comes in on this, but it''s an interesting composition and subject matter.</td>', 'Not sure where the framing comes in on this, but it''s an interesting composition and subject matter.', '2008-01-29 20:12:51.000000', NULL, 1),
(4437580, 637089, 88352, '<td valign="top">Seems overexposed, lots of blown out spots on the statue and girl.</td>', 'Seems overexposed, lots of blown out spots on the statue and girl.', '2008-01-29 20:13:16.000000', NULL, 1),
(4437582, 636940, 88352, '<td valign="top">Very neat architecture photo, I love the twisting and turning relative to the trees!</td>', 'Very neat architecture photo, I love the twisting and turning relative to the trees!', '2008-01-29 20:13:43.000000', NULL, 1),
(4437585, 636881, 88352, '<td valign="top">The eye is out of focus</td>', 'The eye is out of focus', '2008-01-29 20:15:41.000000', NULL, 1),
(4437588, 637019, 88352, '<td valign="top">Seems to have a yellow cast to it, needs some color adjustments.</td>', 'Seems to have a yellow cast to it, needs some color adjustments.', '2008-01-29 20:16:16.000000', NULL, 1),
(4437589, 634194, 88352, '<td valign="top">Very cool, I love how the whole photo isn''t framed, but your eye is drawn to the focal point by the framing.  All I would suggest is a tighter crop.</td>', 'Very cool, I love how the whole photo isn''t framed, but your eye is drawn to the focal point by the framing.  All I would suggest is a tighter crop.', '2008-01-29 20:17:08.000000', NULL, 1),
(4437593, 635715, 88352, '<td valign="top">Haha!  Cute.</td>', 'Haha!  Cute.', '2008-01-29 20:18:16.000000', NULL, 1),
(4437595, 635634, 88352, '<td valign="top">I think you''re trying to get the framing by the tree, but it''s not working out.  Needs more tree.</td>', 'I think you''re trying to get the framing by the tree, but it''s not working out.  Needs more tree.', '2008-01-29 20:19:03.000000', NULL, 1),
(4437599, 636634, 88352, '<td valign="top">May need a little more contrast to take out the foggy look.</td>', 'May need a little more contrast to take out the foggy look.', '2008-01-29 20:20:12.000000', NULL, 1),
(4437601, 635912, 88352, '<td valign="top">Good composition.</td>', 'Good composition.', '2008-01-29 20:20:24.000000', NULL, 1),
(4437602, 635489, 88352, '<td valign="top">Very nice photo, love the composition.</td>', 'Very nice photo, love the composition.', '2008-01-29 20:20:41.000000', NULL, 1),
(4437607, 636730, 88352, '<td valign="top">Is that Amy Winehouse?  ;)  Very cool take on this, the only thing that bugs me is that it''s in the middle of the frame.</td>', 'Is that Amy Winehouse?  ;)  Very cool take on this, the only thing that bugs me is that it''s in the middle of the frame.', '2008-01-29 20:21:31.000000', NULL, 1),
