(4439282, 635326, 66384, '<td valign="top">To me, this feels more pinched than framed. It''s an interesting shot though with a very strong mood.</td>', 'To me, this feels more pinched than framed. It''s an interesting shot though with a very strong mood.', '2008-01-30 09:59:05.000000', NULL, 0),
(4439307, 636602, 66384, '<td valign="top">Lovely b&amp;w and very nice framing with the trees. The fence does cut the image in half, and I find myself wishing the fence wasn''t there. My eye travels out to the horizon and the fence seem to cut off my view. From the "perfect world" stand point, this would be great with the rock shoreline and no fence.</td>', 'Lovely b&w and very nice framing with the trees. The fence does cut the image in half, and I find myself wishing the fence wasn''t there. My eye travels out to the horizon and the fence seem to cut off my view. From the "perfect world" stand point, this would be great with the rock shoreline and no fence.', '2008-01-30 10:06:33.000000', NULL, 0),
(4439327, 636972, 83128, '<td valign="top">Thanx everyone for voting. glad it made it over 5</td>', 'Thanx everyone for voting. glad it made it over 5', '2008-01-30 10:10:57.000000', NULL, 0),
(4439353, 637070, 66384, '<td valign="top">I think the main reason people didn''t see this as having a frame is because the large shadow across the center makes the image look more striped than framed. Still, I like the image, and think it meets the challenge.</td>', 'I think the main reason people didn''t see this as having a frame is because the large shadow across the center makes the image look more striped than framed. Still, I like the image, and think it meets the challenge.', '2008-01-30 10:15:21.000000', NULL, 0),
(4439386, 635047, 66384, '<td valign="top">Nice choice for framing. I like the shot, and think you did a good job with the natural light. I just wish the pacifier wasn''t there obscuring the child''s face.</td>', 'Nice choice for framing. I like the shot, and think you did a good job with the natural light. I just wish the pacifier wasn''t there obscuring the child''s face.', '2008-01-30 10:20:33.000000', NULL, 0),
(4439404, 634194, 72268, '<td valign="top">Very creative, and intersting and beautiful. Great work. I would love to see more of your work.</td>', 'Very creative, and intersting and beautiful. Great work. I would love to see more of your work.', '2008-01-30 10:23:22.000000', NULL, 0),
(4439450, 637070, 62318, '<td valign="top">Haha, I saw this in the challenge and had a feeling it was you. I need to start calling these out when voting. :0<br/> <br/>I think this is wonderfully framed. It si out of the ordinary, yet at the same time still prominent. Oh well. Next time carry a picture frame with you</td>', 'Haha, I saw this in the challenge and had a feeling it was you. I need to start calling these out when voting. :0 I think this is wonderfully framed. It si out of the ordinary, yet at the same time still prominent. Oh well. Next time carry a picture frame with you', '2008-01-30 10:30:20.000000', NULL, 0),
(4439462, 637070, 33672, '<td valign="top">Nice out of the box shot. Too bad Dpc doesn''t reward these type of shots with high scores. Your reward should be that its an above average photo. Very nice work. I did see the framing but found the big shadow a bit of a detraction therefore I gave it a 6. In the end its only my humble opinion.<br/>I certainly disagree that you need to see examples.<br/><br/><i>Message edited by author 2008-01-30 10:33:25.</i></td>', 'Nice out of the box shot. Too bad Dpc doesn''t reward these type of shots with high scores. Your reward should be that its an above average photo. Very nice work. I did see the framing but found the big shadow a bit of a detraction therefore I gave it a 6. In the end its only my humble opinion.I certainly disagree that you need to see examples.', '2008-01-30 10:32:25.000000', '2008-01-30 10:33:25.000000', 0),
(4439464, 636741, 52549, '<td valign="top">Excellent capture (had a feeling this was yours). Big congrats on the blue, Jaime.</td>', 'Excellent capture (had a feeling this was yours). Big congrats on the blue, Jaime.', '2008-01-30 10:32:31.000000', NULL, 0),
(4439468, 634194, 52549, '<td valign="top">Such a creative and subtle image. Wonderful work, congratulations on your red.</td>', 'Such a creative and subtle image. Wonderful work, congratulations on your red.', '2008-01-30 10:33:26.000000', NULL, 0),
(4439472, 635867, 52549, '<td valign="top">Lovely shot. Congrats on your yellow ribbon.</td>', 'Lovely shot. Congrats on your yellow ribbon.', '2008-01-30 10:33:57.000000', NULL, 0),
(4439476, 636848, 62318, '<td valign="top">You have two frames going on here, cheater. ;)<br/> <br/>For some reason, I think a lot of these voters need to go to a photog class and then take a bit on framing. Rule of thumb though, complex composition = bad news. Well, at least here on DPC, but I keep shooting them anyways. <br/> <br/>As for the actual shot, it is brilliant. Not sure why people don''t get shots like this. Personally, this one does not even need a title, the image is self explanatory and absorbing. Oh well.</td>', 'You have two frames going on here, cheater. ;) For some reason, I think a lot of these voters need to go to a photog class and then take a bit on framing. Rule of thumb though, complex composition = bad news. Well, at least here on DPC, but I keep shooting them anyways.  As for the actual shot, it is brilliant. Not sure why people don''t get shots like this. Personally, this one does not even need a title, the image is self explanatory and absorbing. Oh well.', '2008-01-30 10:34:20.000000', NULL, 0),
(4439586, 637070, 70661, '<td valign="top">LOVE IT! :)</td>', 'LOVE IT! :)', '2008-01-30 10:53:14.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4439589, 636820, 24454, '<td valign="top">I actually am kind of with you on the nose being in focus part.  It makes it look like she is poking her nose right out of your computer at you :)<br/> <br/>Lately, I have been so bored with "rule" pictures and have wanted to daringly do things that just don''t follow all the rigid rules.   For me. . .this works!<br/> <br/></td>', 'I actually am kind of with you on the nose being in focus part.  It makes it look like she is poking her nose right out of your computer at you :) Lately, I have been so bored with "rule" pictures and have wanted to daringly do things that just don''t follow all the rigid rules.   For me. . .this works! ', '2008-01-30 10:55:53.000000', NULL, 0),
(4439628, 636741, 43410, '<td valign="top">perfectly framed, amazing shot!  very well deserved :)</td>', 'perfectly framed, amazing shot!  very well deserved :)', '2008-01-30 11:08:21.000000', NULL, 0),
(4439699, 634194, 73250, '<td valign="top">This is so well conceived and carried out. The colors are amazing. Congrats!</td>', 'This is so well conceived and carried out. The colors are amazing. Congrats!', '2008-01-30 11:30:43.000000', NULL, 0),
(4439803, 634597, 40718, '<td valign="top">Technicals:  I like your composition.  The geometric pattern is strong and pleasing to the eye.  I can''t quite decide if it would be better in B&amp;W since the greens are not strong (due to the shadows).<br/> <br/>The feel:  One big question is...what are you framing?  I bet you would have gained at least .2 in score by putting a person at the end of the tunnel.</td>', 'Technicals:  I like your composition.  The geometric pattern is strong and pleasing to the eye.  I can''t quite decide if it would be better in B&W since the greens are not strong (due to the shadows). The feel:  One big question is...what are you framing?  I bet you would have gained at least .2 in score by putting a person at the end of the tunnel.', '2008-01-30 11:57:45.000000', NULL, 0),
(4439806, 636820, 65083, '<td valign="top">Hey I like this who cares about the eyes.  It is a total cat shot.</td>', 'Hey I like this who cares about the eyes.  It is a total cat shot.', '2008-01-30 11:58:37.000000', NULL, 0),
(4439847, 636741, 42013, '<td valign="top">Who''s on fire! Big congrats!</td>', 'Who''s on fire! Big congrats!', '2008-01-30 12:10:43.000000', NULL, 0),
(4439857, 635494, 40718, '<td valign="top">Technicals:  Your composition is decent, although it may have been better to use the trees as a "frame within a frame".  In other words, zoom out more so the trees are not at the edge of the picture.  Color is decent.  A nice blue sky.  The picture looks like it could use some sharpness.  I don''t know if that was processing or just your lens.  Lighting is good.  You picked a decent time of day to shoot this.<br/> <br/>The feel: As the picture is, we look at it and move on fairly quickly.  Pulling back, as mentioned, might add interest and I discovered over the years, that clouds (when they look nice) add a ton to a picture instead of a plain blue sky.  Naturally you can''t command clouds to appear when you want, but it is a possible way to improve the shot on a different occasion.</td>', 'Technicals:  Your composition is decent, although it may have been better to use the trees as a "frame within a frame".  In other words, zoom out more so the trees are not at the edge of the picture.  Color is decent.  A nice blue sky.  The picture looks like it could use some sharpness.  I don''t know if that was processing or just your lens.  Lighting is good.  You picked a decent time of day to shoot this. The feel: As the picture is, we look at it and move on fairly quickly.  Pulling back, as mentioned, might add interest and I discovered over the years, that clouds (when they look nice) add a ton to a picture instead of a plain blue sky.  Naturally you can''t command clouds to appear when you want, but it is a possible way to improve the shot on a different occasion.', '2008-01-30 12:14:00.000000', NULL, 0),
(4439907, 634984, 67855, '<td valign="top">Good picture but a think if you have make your photo without tourists group (excep the old man with a hat on the first plan) it''s more better !<br/>;)</td>', 'Good picture but a think if you have make your photo without tourists group (excep the old man with a hat on the first plan) it''s more better !;)', '2008-01-30 12:25:47.000000', NULL, 0),
(4439937, 636940, 82099, '<td valign="top">Wow.  I think this should have gotten first.  Very interesting picture!! Leads the eye all over the place.</td>', 'Wow.  I think this should have gotten first.  Very interesting picture!! Leads the eye all over the place.', '2008-01-30 12:36:44.000000', NULL, 0),
(4439940, 634194, 42013, '<td valign="top">Congrats on this fine shot and your Ribbon!</td>', 'Congrats on this fine shot and your Ribbon!', '2008-01-30 12:37:54.000000', NULL, 0),
(4440058, 635489, 52549, '<td valign="top">This is a beautiful image. Congratulations on top 10, Alex.</td>', 'This is a beautiful image. Congratulations on top 10, Alex.', '2008-01-30 13:05:15.000000', NULL, 0),
(4440060, 636835, 52549, '<td valign="top">This was one of my top favourites of this challenge. Glad you made top 10. Congrats, Tate.</td>', 'This was one of my top favourites of this challenge. Glad you made top 10. Congrats, Tate.', '2008-01-30 13:06:12.000000', NULL, 0),
